def hx(s):
    return ''.join(chr(int(s[i:i + 4], 16)) for i in range(0, len(s), 4))


def apply(text, table, label, where, printer):
    done = skipped = 0
    for row in sorted(table, reverse=True):
        off, word, subs = row[0], row[1], row[2]
        old = hx(word)
        new = list(old)
        for i, cp in subs:
            new[i] = chr(int(cp, 16))
        new = ''.join(new)
        here = text[off:off + len(old)]
        if here == new:
            skipped += 1
            continue
        assert here == old, (
            f'{label} @{off}: found {[hex(ord(c)) for c in here]}, expected '
            f'{[hex(ord(c)) for c in old]} - {where} has moved under this table')
        assert len(new) == len(old)
        text = text[:off] + new + text[off + len(old):]
        printer(row, old)
        done += 1
    return text, done, skipped


def main(write=False):
    total = skipped = body = 0
    classes, source = Counter(), Counter()
    for lesson in sorted(set(FIXES) | set(BODY)):
        p = ROOT / f'{lesson:02d}.json'
        L = json.loads(p.read_text(encoding='utf-8'))
        print(f'  lesson {lesson:02d}')
        n = 0

        def show(row, old):
            classes.update(cp for _, cp in row[2])
            source[row[3]] += 1
            print(f'    @{row[0]:<6} {row[5]:<26} {row[3]:<5} {row[4]}')

        fn = L.get('arabicFootnotes') or ''
        if lesson in FIXES:
            fn, d, s = apply(fn, FIXES[lesson], f'lesson {lesson:02d} footnote',
                             'arabicFootnotes', show)
            L['arabicFootnotes'] = fn
            n += d; total += d; skipped += s

        def show_body(row, old):
            print(f'    @{row[0]:<6} BODY  {row[3]}')

        if lesson in BODY:
            b, d, s = apply(L['arabicBody'], BODY[lesson],
                            f'lesson {lesson:02d} body', 'arabicBody', show_body)
            L['arabicBody'] = b
            n += d; body += d; skipped += s

        if write and n:
            p.write_text(json.dumps(L, ensure_ascii=False), encoding='utf-8')
    print(f'\n{total} footnote words repaired, {body} body word'
          + (f', {skipped} already done' if skipped else ''))
    for k, v in source.most_common():
        print(f'  settled by {k}: {v}')
    for k, v in classes.most_common(12):
        print(f'  ->{k}  {v}')
    if write:
        print('WRITTEN')


if __name__ == '__main__':
    main('--write' in sys.argv)
